import {readFile} from 'node:fs/promises';
import assert from 'node:assert/strict';
const source=await readFile('/workspace/src/session.js');
const {createResource}=await import("'`data:text/javascript;base64,${source.toString('"'base64')}"'`);
const checks=[];
const scheduled=new Map();
const callbacks=[];
let nextTimer=1;
const host={
  publish(){},
  check(token){return new Promise(resolve=>checks.push({token,resolve}));},
  schedule(callback){const id=nextTimer++;scheduled.set(id,callback);callbacks.push({id,callback});return id;},
  cancel(id){scheduled.delete(id);}
};
const flush=()=>new Promise(resolve=>queueMicrotask(resolve));
const resource=createResource(host,'"'download','first');
resource.start();
assert.equal(checks.length,1);
checks.shift().resolve(false); await flush();
assert.equal(resource.snapshot().retryScheduled,true);
assert.equal(scheduled.size,1);
let job=callbacks.at(-1); scheduled.get(job.id)();
assert.equal(checks.length,1);
checks.shift().resolve(false); await flush();
assert.equal(resource.snapshot().retryScheduled,true);
assert.equal(scheduled.size,1);
job=callbacks.at(-1); scheduled.get(job.id)();
assert.equal(checks.length,1);
checks.shift().resolve(true); await flush();
assert.deepEqual(resource.snapshot().completed,['first']);
assert.equal(resource.snapshot().retryScheduled,false);
assert.equal(scheduled.size,0);

resource.start();
checks.shift().resolve(false); await flush();
const stale=callbacks.at(-1);
resource.close();
assert.equal(scheduled.has(stale.id),false);
stale.callback();
assert.equal(checks.length,0);
resource.reopen('second');
assert.equal(checks.length,1);
checks.shift().resolve(true); await flush();
assert.deepEqual(resource.snapshot().completed,['first','second']);
console.log('pending retry, repeated pending, ready completion, and close/reopen invalidation: ok');
